mapper.select:
SELECT u.*
FROM user u

    1 = 1

        AND u.id = #{id}


        AND u.user_name = #{userName}


        AND u.user_account = #{userAccount}


        AND u.phone = #{phone}


LIMIT 1

SELECT u.*
FROM user u


        AND u.user_account LIKE concat('%',#{userAccount},'%')


        AND u.user_name LIKE concat('%',#{userName},'%')


        AND u.user_email LIKE concat('%',#{userEmail},'%')


        AND u.phone LIKE concat('%',#{phone},'%')


        AND u.role = #{role}


        AND u.is_login = #{isLogin}


        AND u.is_word = #{isWord}


        AND u.create_time BETWEEN #{startTime} AND #{endTime}


ORDER BY u.id DESC

    LIMIT #{current},#{size}

SELECT COUNT(*)
FROM user u


        AND u.user_account LIKE concat('%',#{userAccount},'%')


        AND u.user_name LIKE concat('%',#{userName},'%')


        AND u.user_email LIKE concat('%',#{userEmail},'%')


        AND u.phone LIKE concat('%',#{phone},'%')


        AND u.role = #{role}


        AND u.is_login = #{isLogin}


        AND u.is_word = #{isWord}


        AND u.create_time BETWEEN #{startTime} AND #{endTime}

SELECT u.id, u.user_account, u.user_name, u.user_avatar, u.user_email, u.phone, u.phone_verified, u.user_role, u.is_login, u.is_word, u.is_vip, u.vip_expire_time, u.create_time FROM user u WHERE u.user_role = 2
AND (u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.user_account LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY CASE WHEN u.user_name LIKE CONCAT(#{keyword}, '%') THEN 0 WHEN u.phone LIKE CONCAT(#{keyword}, '%') THEN 1 ELSE 2 END, u.id ASC LIMIT #{limit}

SELECT COUNT(*) FROM user
WHERE phone = #{phone}
AND id != #{excludeId}
